    for (size_t i = 0; i < n; ++i) {
        const Point_2& p1 = polygon[i];
        const Point_2& p2 = polygon[(i + 1) % n];

        // Check if point is on the boundary
        // A point P is on segment P1P2 if it is collinear and within the bounding box of P1P2
        double min_x = std::min(p1.x(), p2.x());
        double max_x = std::max(p1.x(), p2.x());
        double min_y = std::min(p1.y(), p2.y());
        double max_y = std::max(p1.y(), p2.y());

        if (point.x() >= min_x && point.x() <= max_x &&
            point.y() >= min_y && point.y() <= max_y) {
            // Use cross product to check collinearity: (p2-p1) x (point-p1) == 0
            if (std::abs((p2.x() - p1.x()) * (point.y() - p1.y()) - 
                        (p2.y() - p1.y()) * (point.x() - p1.x())) < 1e-9) {
                return CGAL::ON_BOUNDARY;
            }
        }

        // Ray casting algorithm
        if (((p1.y() > point.y()) != (p2.y() > point.y())) &&
            (point.x() < (p2.x() - p1.x()) * (point.y() - p1.y()) / (p2.y() - p1.y()) + p1.x())) {
            inside = !inside;
        }
    }

    return inside ? CGAL::ON_BOUNDED_SIDE : CGAL::ON_UNBOUNDED_SIDE;

